"""Unit 10: Linear Programming (7 skills). Feasible regions, vertices and optima are computed exactly with fractions by
intersecting every pair of boundary lines and keeping the feasible points. Boundedness is checked along the objective
direction; infeasible, unbounded and multiple-optimum cases are flagged by the engine. x ≥ 0 and y ≥ 0 are always included."""
import itertools
from fractions import Fraction as Fr
from core import Bank, frac, seeded
import figs

U = 'linear-programming'


def build():
    b = Bank(U, 'lp', 7)
    for f in (s1, s2, s3, s4, s5, s6, s7, topup, topup2, topup3, errors):
        f(b)
    return b


def num_mc(b, k, L, prompt, ans, wr, steps, fam):
    ws = [str(w) for w in dict.fromkeys(wr) if str(w) != str(ans)]
    return b.mc(k, L, prompt, str(ans), ws[:3], steps, fam, order='sort')


# constraint: (a, b, c) meaning a x + b y <= c
def feasible(p, cons):
    x, y = p
    return x >= 0 and y >= 0 and all(a * x + bb * y <= c for a, bb, c in cons)


def vertices(cons):
    allc = list(cons) + [(-1, 0, 0), (0, -1, 0)]
    pts = set()
    for (a1, b1, c1), (a2, b2, c2) in itertools.combinations(allc, 2):
        det = a1 * b2 - a2 * b1
        if det == 0:
            continue
        x = Fr(c1 * b2 - c2 * b1, det)
        y = Fr(a1 * c2 - a2 * c1, det)
        if feasible((x, y), cons):
            pts.add((x, y))
    return sorted(pts)


def bounded_dir(cons, d):
    """Is the objective direction d=(p,q) bounded above on the region? Check recession directions (r with a·r <= 0, r >= 0)."""
    # recession cone generated by extreme rays; test rays from the cone's boundary directions
    rays = [(Fr(1), Fr(0)), (Fr(0), Fr(1))]
    for a, bb, c in cons:
        if bb != 0:
            rays.append((Fr(1), Fr(-a, bb)) if bb > 0 else (Fr(-1), Fr(a, -bb)))
            rays.append((-rays[-1][0], -rays[-1][1]))
    for r in rays:
        if r[0] >= 0 and r[1] >= 0 and (r[0] or r[1]) and all(a * r[0] + bb * r[1] <= 0 for a, bb, c in cons):
            if d[0] * r[0] + d[1] * r[1] > 0:
                return False
    return True


def solve(cons, obj, sense):
    V = vertices(cons)
    if not V:
        return {'status': 'infeasible', 'V': V}
    p, q = obj
    d = (p, q) if sense == 'max' else (-p, -q)
    if not bounded_dir(cons, d):
        return {'status': 'unbounded', 'V': V}
    vals = {v: p * v[0] + q * v[1] for v in V}
    best = max(vals.values()) if sense == 'max' else min(vals.values())
    arg = [v for v in V if vals[v] == best]
    return {'status': 'multiple' if len(arg) > 1 else 'unique', 'V': V, 'vals': vals, 'best': best, 'arg': arg}


def P(v):
    return '(%s, %s)' % (frac(v[0]), frac(v[1]))


def ctext(cons, names=('x', 'y')):
    out = []
    for a, bb, c in cons:
        sgn = '≤'
        if a <= 0 and bb <= 0 and (a or bb):
            a, bb, c, sgn = -a, -bb, -c, '≥'
        terms = []
        for coef, v in ((a, names[0]), (bb, names[1])):
            if coef == 0:
                continue
            s = ('' if abs(coef) == 1 else frac(abs(coef))) + v
            terms.append(('− ' if coef < 0 else '+ ') + s if terms else ('−' if coef < 0 else '') + s)
        out.append('%s %s %s' % (' '.join(terms), sgn, frac(c)))
    return out + ['%s ≥ 0' % names[0], '%s ≥ 0' % names[1]]


def objtext(obj, names=('x', 'y')):
    p, q = obj
    return '%s%s %s %s%s' % ('' if p == 1 else frac(p), names[0], '+' if q >= 0 else '−', '' if abs(q) == 1 else frac(abs(q)), names[1])


LPS = {  # name: (constraints, objective, sense, xmax, ymax)
    'L1': ([(1, 1, 8), (1, 0, 5)], (3, 2), 'max', 9, 9),
    'L2': ([(2, 1, 10), (1, 2, 8)], (3, 4), 'max', 6, 6),
    'L3': ([(1, 1, 10), (1, 3, 18), (1, 0, 8)], (2, 3), 'max', 11, 11),
    'L4': ([(-1, -1, -6), (-1, -2, -8)], (2, 3), 'min', 10, 8),
    'L5': ([(1, 2, 12), (3, 2, 18)], (1, 2), 'max', 8, 8),
    'L6': ([(-1, -1, -4), (1, 0, 6)], (1, 1), 'max', 8, 8),
    'L7': ([(1, 1, 3), (-1, -1, -5)], (1, 1), 'max', 6, 6),
    'L8': ([(-2, -1, -8), (-1, -3, -9)], (4, 3), 'min', 10, 9),
    'L9': ([(1, 1, 40), (2, 1, 60), (0, 1, 30)], (30, 20), 'max', 32, 42),
}


def lp_alt(key):
    cons, obj, sense, *_ = LPS[key]
    return 'Graph of the feasible region for ' + ', '.join(ctext(cons)) + ', with its corner points marked.'


def lp_pic(key, labels=True):
    cons, obj, sense, xm, ym = LPS[key]
    V = vertices(cons)
    return figs.region(U, key + ('' if labels else '_nolabel'), [(a, bb, c, '') for a, bb, c in cons], xm, ym, vertices=V, labels=labels)


# ---------------------------------------------------------------- 1. writing constraints
